<?php
namespace App\Http\Controllers;use App\Http\Requests\StoreCommitteeCommitmentRequest;use App\Models\{Committee,CommitteeCommitment};use App\Services\CommitteeCommitmentService;use Illuminate\Http\Request;
class CommitteeCommitmentController extends Controller{public function store(Committee $committee,StoreCommitteeCommitmentRequest $request,CommitteeCommitmentService $service){$service->create($committee,$request->validated(),$request->user()->id);return back()->with('success','Compromiso creado.');}public function followup(CommitteeCommitment $commitment,Request $request,CommitteeCommitmentService $service){$data=$request->validate(['followup_date'=>'required|date','progress'=>'required|integer|min:0|max:100','comment'=>'required|string|max:3000','evidence'=>'nullable|file|mimes:pdf,jpg,jpeg,png,webp,doc,docx,xls,xlsx|max:5120']);$file=$request->file('evidence');unset($data['evidence']);$service->followup($commitment,$data,$file,$request->user()->id);return back()->with('success','Seguimiento registrado.');}}
